class Solution:
    def numRookCaptures(self, board):
        ans = 0
        for i in range(8):
            for j in range(8):
                if board[i][j] != 'p':
                    continue
                for di, dj in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                    x, y = i + di, j + dj
                    while 0 <= x < 8 and 0 <= y < 8 and board[x][y] == '.':
                        x += di
                        y += dj
                    if 0 <= x < 8 and 0 <= y < 8 and board[x][y] == 'R':
                        ans += 1
        return ans

