class Solution {
public:
    int numRookCaptures(vector<vector<char>>& board) {
        int ans = 0;
        int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
        for (int i = 0; i < 8; i++)
            for (int j = 0; j < 8; j++) {
                if (board[i][j] != 'p') continue;
                for (auto& d : dirs) {
                    int x = i + d[0], y = j + d[1];
                    while (x >= 0 && x < 8 && y >= 0 && y < 8 && board[x][y] == '.') {
                        x += d[0]; y += d[1];
                    }
                    if (x >= 0 && x < 8 && y >= 0 && y < 8 && board[x][y] == 'R') ans++;
                }
            }
        return ans;
    }
};

